package api

// WP-PRICE-1 (Stage 1a Prompt 49): /pricing is a page, generated by `make
// landing` from prices.json like the landing — never typed. Every price in
// the file is on it, no other dollar figure is, and it is a web page only:
// an S3 client asking for a bucket named "pricing", or any request on the
// s3.* host, gets the S3 API as before.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"regexp"
	"strconv"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/FairForge/vaultaire/internal/hosts"
	"github.com/FairForge/vaultaire/internal/usage"
)

// pricesFileNumbers walks prices.json: every number whose key is not a
// ratio, by its dotted path.
func pricesFileNumbers(t *testing.T) map[string]float64 {
	t.Helper()
	raw, err := os.ReadFile("landing/prices.json")
	require.NoError(t, err)
	var doc map[string]any
	require.NoError(t, json.Unmarshal(raw, &doc))
	out := map[string]float64{}
	var walk func(prefix string, v any)
	walk = func(prefix string, v any) {
		switch x := v.(type) {
		case map[string]any:
			for k, vv := range x {
				walk(strings.TrimPrefix(prefix+"."+k, "."), vv)
			}
		case float64:
			if !strings.HasSuffix(prefix, "_ratio") {
				out[prefix] = x
			}
		}
	}
	walk("", doc)
	return out
}

// visibleText is the page without its <style> and <script> blocks.
func visibleText(page string) string {
	page = regexp.MustCompile(`(?s)<style.*?</style>`).ReplaceAllString(page, "")
	return regexp.MustCompile(`(?s)<script.*?</script>`).ReplaceAllString(page, "")
}

func pricingPageBody(t *testing.T) string {
	t.Helper()
	return string(mustRenderPricing(false, hosts.FromEnv(func(string) string { return "" }, 8000, nil)))
}

func TestPricingPage_EveryNumberFromPricesJSON(t *testing.T) {
	page := pricingPageBody(t)
	text := visibleText(page)
	nums := pricesFileNumbers(t)
	require.NotEmpty(t, nums)

	allowed := map[string]bool{"$0": true} // what an API call costs
	for path, v := range nums {
		two := "$" + strconv.FormatFloat(v, 'f', 2, 64)
		short := "$" + strconv.FormatFloat(v, 'g', -1, 64)
		allowed[two], allowed[short] = true, true
		assert.True(t, strings.Contains(text, two) || strings.Contains(text, short), "%s (%s) is on the page", path, two)
	}
	for _, m := range regexp.MustCompile(`\$[0-9][0-9,]*(?:\.[0-9]+)?`).FindAllString(text, -1) {
		assert.True(t, allowed[m], "the dollar figure %s is not a number of prices.json", m)
	}

	p := pricesFile(t)
	for _, s := range []string{p.Egress.PastAllowance, p.Egress.OneAllowance, p.Competitors.AsOf} {
		assert.Contains(t, text, s)
	}
	assert.Contains(t, text, fmt.Sprintf("%d GB", usage.FreeTierLimits.StorageBytes/1_000_000_000), "the free tier")
	assert.Contains(t, text, "100 MB", "the edge's single-request limit")
	for _, never := range []string{"API calls", "Vault restores"} {
		assert.Contains(t, text, never)
	}
	assert.Contains(t, page, `<form`, "the calculator is a form")
}

// pricesFile is the typed view of prices.json the page reads.
type pricesFileView struct {
	Egress struct {
		PastAllowance string `json:"past_allowance"`
		OneAllowance  string `json:"one_allowance"`
	} `json:"egress"`
	Competitors struct {
		AsOf string `json:"_asof"`
	} `json:"competitors"`
}

func pricesFile(t *testing.T) pricesFileView {
	t.Helper()
	raw, err := os.ReadFile("landing/prices.json")
	require.NoError(t, err)
	var p pricesFileView
	require.NoError(t, json.Unmarshal(raw, &p))
	return p
}

func TestPricingPage_ServedOnTheWebHostsOnly(t *testing.T) {
	for _, env := range []map[string]string{prodTodayHosts, prodTargetHosts} {
		h := webServer(t, env)
		w := webReq{host: "stored.cloud", path: "/pricing", accept: browserAccept}.do(h)
		require.Equal(t, http.StatusOK, w.Code)
		assert.Contains(t, w.Header().Get("Content-Type"), "text/html")
		assert.Contains(t, w.Body.String(), "<title>Pricing")
		w = webReq{host: "stored.cloud", path: "/pricing/", accept: browserAccept}.do(h)
		assert.Equal(t, http.StatusMovedPermanently, w.Code)
		assert.Equal(t, "/pricing", w.Header().Get("Location"))
		// Anything else is the S3 API's, as before.
		assertS3XML(t, webReq{host: "stored.cloud", path: "/pricing", accept: "*/*"}.do(h), "curl /pricing")
		assertS3XML(t, webReq{host: "s3.stored.cloud", path: "/pricing", accept: browserAccept}.do(h), "s3 host /pricing")
	}
}

func TestLlmsTxt_LinksThePricingPage(t *testing.T) {
	assert.Contains(t, llmsTxtBody(hosts.FromEnv(func(string) string { return "" }, 8000, nil)), "GET /pricing")
}

func TestSitemap_ListsPricing(t *testing.T) {
	assert.Contains(t, (&Server{}).sitemapPaths(), "/pricing")
}

func TestLanding_LinksThePricingPage(t *testing.T) {
	assert.Contains(t, landingTemplateSrc, `href="/pricing"`)
	faq, err := os.ReadFile("docs_faq.md")
	require.NoError(t, err)
	assert.Contains(t, string(faq), "(/pricing)")
}
